// WF12 Market Intelligence Report Builder config — v0.3 stakeholder report (DEC-112/118/122/128).
// $0 by default: no Claude, no Telegram send, no external API. Reads WF10 tabs + competitor_site_snapshots
// + public_lead_signals; writes ONE market_intelligence_reports row (25 cols, MARKET_INTELLIGENCE_REPORT_SCHEMA.md v0.3),
// ONE agent_requests row and ONE live_source_runs row.
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const stamp=moscowStamp();
return [{ json: {
  // --- hard-off defaults (DEC-112): the deterministic report is complete without any of these.
  enable_llm_summary:false,          // optional Claude summary branch — guarded, HTTP node DISABLED
  llm_approval_token:'',             // must equal 'I_APPROVE_CLAUDE_REPORT_SUMMARY' (explicit operator approval)
  llm_model:'claude-sonnet-4-6',     // project stack model (CLAUDE.md); pricing for cost tracking below
  llm_max_tokens:1200,               // hard output cap for the summary
  llm_max_input_chars:8000,          // budget guard (DEC-128): prompt facts hard-capped at this size
  llm_max_estimated_cost_usd:0.10,   // budget guard (DEC-128): throw BEFORE the HTTP node if estimate exceeds
  llm_input_price_per_mtok:3.0,      // USD per 1M input tokens (claude-sonnet-4-6)
  llm_output_price_per_mtok:15.0,    // USD per 1M output tokens (claude-sonnet-4-6)
  telegram_send:false,               // Telegram delivery — NOT implemented (delivered_to stays 'none')
  report_type:'on_demand',           // on_demand / weekly_digest / no_data_notice (auto-set on no_data)
  niche_id:'credit_brokerage',
  region:'Москва/МО',
  top_n:3,
  max_offer_chars:90,                // v0.3: long competitor offers are shortened for readability
  requested_by:'operator',
  report_id:'report_'+stamp,
  run_id:'wf12_'+stamp,
  agent_request_id:'wf12_req_'+stamp,
  created_at:moscowIsoNow()
}}];

// Deterministic Report Builder core v0.3 (DEC-112/118/122/128): latest WF10 snapshot + website snapshots
// + public lead signals -> 25-col report row + stakeholder Markdown. Facts only — every number/name comes
// from sheet rows; nothing is invented; no contacts are surfaced; no outreach recommendations.
function str(v){return v==null?'':String(v).trim();}
function num(v){var n=Number(v);return isFinite(n)?n:0;}
function low(v){return str(v).toLowerCase();}
function cut(s,n){s=str(s);return s.length>n?(s.slice(0,n-1)+'…'):s;}
// Defect A (C6): deterministic report-layer contact redaction. Removes direct contact identifiers that may be
// embedded in lead evidence text (phones, @handles, t.me/VK profile links, emails) BEFORE truncation/formatting,
// while preserving business numbers (amounts, %, rates, dates) and ordinary source-POST URLs (vk.com/wall...).
const CONTACT_MARK='[PUBLIC CONTACT REDACTED]';
function redact(s){ s=str(s); if(!s)return s;
  s=s.replace(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g,CONTACT_MARK);            // emails (before @handle)
  s=s.replace(/(?:\+7|8)[\s\-()]*\d{3}[\s\-()]*\d{3}[\s\-]*\d{2}[\s\-]*\d{2}/g,CONTACT_MARK); // RU phones
  s=s.replace(/\+\d[\d\s().\-]{8,}\d/g,CONTACT_MARK);                                       // intl phone-like
  s=s.replace(/(?:https?:\/\/)?(?:t|telegram)\.me\/[A-Za-z0-9_+]+/gi,CONTACT_MARK);          // telegram links
  s=s.replace(/@[A-Za-z0-9_]{3,32}/g,CONTACT_MARK);                                            // @handles
  s=s.replace(/(?:https?:\/\/)?(?:www\.)?vk\.com\/(?!wall)[A-Za-z0-9_.]+/gi,CONTACT_MARK);   // VK profiles/groups (keep wall posts)
  return s;
}
function rowsOf(name){try{return $(name).all().map(i=>i.json).filter(r=>r&&Object.keys(r).some(k=>str(r[k])!==''));}catch(e){return [];}}
const cfg=$('Set Report Config').first().json;
const topN=Number(cfg.top_n)||3;
const maxOffer=Number(cfg.max_offer_chars)||90;
const profiles=rowsOf('Read competitor_profiles');
const angles=rowsOf('Read market_angles');
const signals=rowsOf('Read audience_activity_signals');
const plans=rowsOf('Read content_positioning_plan').filter(p=>str(p.plan_id));
const siteSnaps=rowsOf('Read competitor_site_snapshots');
const leadSignals=rowsOf('Read public_lead_signals');
// --- run selection: plan_id carries the WF10 run stamp (plan_<stamp> or plan_<stamp>_no_data; one plan per run)
function planStamp(p){return str(p.plan_id).replace(/^plan_/,'').replace(/_no_data$/,'');}
plans.sort((a,b)=>planStamp(a)<planStamp(b)?-1:1);
if(!plans.length){throw new Error('WF12: content_positioning_plan is empty — run WF10 at least once before building a report.');}
const latest=plans[plans.length-1];
const stamp=planStamp(latest);
const prev=plans.filter(p=>planStamp(p)!==stamp).pop()||null;
const prevStamp=prev?planStamp(prev):'';
const isNoData=/_no_data$/.test(str(latest.plan_id))||/rows=0/.test(str(latest.source_evidence));
const rowsAfter=(function(){const m=str(latest.source_evidence).match(/rows=(\d+)/);return m?Number(m[1]):0;})();
// --- snapshot filters: WF10 ids/notes carry the run stamp
const profNow=profiles.filter(p=>str(p.notes).indexOf('wf10_'+stamp)>=0||str(p.notes).indexOf(stamp)>=0);
const angNow=angles.filter(a=>str(a.angle_id).endsWith(stamp));
const angPrev=prevStamp?angles.filter(a=>str(a.angle_id).endsWith(prevStamp)):[];
const sigNow=signals.filter(s=>str(s.signal_id).endsWith(stamp));
// --- v0.3 clean competitor names (DEC-128): never show ugly '(unnamed) <long offer>' to a stakeholder.
// Fallback: '<Platform> offer: <short offer text>'.
function capWord(s){s=str(s);return s?(s.charAt(0).toUpperCase()+s.slice(1)):s;}
function cleanName(p){
  const n=str(p.competitor_name);
  if(n&&n.indexOf('(unnamed)')!==0)return cut(n,60);
  const plat=capWord(str(p.platforms).split(/\s*,\s*/)[0]||'market');
  const offer=cut(str(p.offers).split(' | ')[0]||n.replace(/^\(unnamed\)\s*/,''),60);
  return plat+' offer: '+(offer||'(no offer text)');
}
// --- deterministic top lists
const topCompRows=profNow.slice().sort((a,b)=>(num(b.evidence_count)-num(a.evidence_count))||(num(b.source_confidence_score)-num(a.source_confidence_score))).slice(0,topN);
const topComp=topCompRows.map(p=>cleanName(p)+' (evidence '+num(p.evidence_count)+', conf '+num(p.source_confidence_score)+')');
function angleKey(a){return str(a.angle_id).replace(/^angle_/,'').replace(/_\d{8}_\d{6}$/,'');}
const prevFreq={};for(const a of angPrev){prevFreq[angleKey(a)]=num(a.frequency);}
const topAng=angNow.slice().sort((a,b)=>num(b.frequency)-num(a.frequency)).slice(0,topN)
  .map(a=>{const k=angleKey(a);const f=num(a.frequency);let trend='·';
    if(prevStamp){const pf=prevFreq[k];trend=(pf===undefined)?'NEW':(f>pf?'↑':(f<pf?'↓':'='));}
    return str(a.angle_text)+' (x'+f+(prevStamp?(' '+trend):'')+')';});
const audSummary=sigNow.map(s=>str(s.platform)+': questions='+num(s.question_count)+', objections='+num(s.objection_count)+', complaints='+num(s.complaint_count)+', buying_intent='+num(s.buying_intent_count)+(str(s.top_pains)?(', pains: '+str(s.top_pains)):'')).join(' | ');
const NO_DATA_TEXT='no_data; broaden filters or source scope';
// --- v0.3 shortened offers/prices
const offersPrices=profNow.filter(p=>str(p.offers)||str(p.prices_terms)).slice(0,5)
  .map(p=>cleanName(p)+': '+cut(str(p.offers).split(' | ')[0]||'(оффер не извлечён)',maxOffer)+(str(p.prices_terms)?(' — '+cut(str(p.prices_terms).split(' | ')[0],maxOffer)):''));
const confScores=profNow.map(p=>num(p.source_confidence_score)).filter(n=>n>0);
const confAvg=confScores.length?Math.round(confScores.reduce((a,b)=>a+b,0)/confScores.length):0;
const confLine=confScores.length?('avg='+confAvg+', min='+Math.min.apply(null,confScores)+', max='+Math.max.apply(null,confScores)+' (по '+confScores.length+' профилям; правила: source_confidence_rules)'):'(нет профилей в снапшоте)';
const platformsSeen={};profNow.forEach(p=>str(p.platforms).split(/\s*,\s*/).forEach(x=>{if(x)platformsSeen[x]=(platformsSeen[x]||0)+1;}));
const platLine=Object.keys(platformsSeen).map(k=>k+' ('+platformsSeen[k]+')').join(', ')||'(none)';
// --- v0.3 competitor WEBSITE block (Stage 2 reintegration, DEC-129): latest snapshot per domain.
const byDomain={};
for(const s of siteSnaps){const d=low(s.domain)||low(str(s.source_url).replace(/^https?:\/\/(www\.)?/,'').split('/')[0]);if(!d)continue;
  if(!byDomain[d]||str(s.created_at)>str(byDomain[d].created_at))byDomain[d]=s;}
const siteLines=Object.keys(byDomain).slice(0,5).map(d=>{const s=byDomain[d];
  return d+' — '+(str(s.company_name)||'(company n/a)')+': '+cut(str(s.offer_summary)||'(offer n/a)',maxOffer)
   +(str(s.prices_terms)?(' · цены: '+cut(s.prices_terms,60)):'')
   +(str(s.guarantees)?(' · гарантии: '+cut(s.guarantees,60)):'')
   +(str(s.cta_text)?(' · CTA: '+cut(s.cta_text,50)):'')
   +(str(s.change_type)&&low(s.change_type)!=='baseline'?(' · изменение: '+str(s.change_type)):'');});
const webProfiles=profNow.filter(p=>/web|site|сайт/.test(low(str(p.platforms)+' '+str(p.ad_channels))));
const siteChanged=Object.keys(byDomain).filter(d=>['changed','new_offer','price_change'].indexOf(low(byDomain[d].change_type))>=0).length;
// --- public lead / audience signal block (Lead Scout v0.3, Stage 3.5): AGGREGATES + anonymized summaries.
// NO contacts/phones/usernames/profile URLs are ever surfaced — only counts + safe evidence excerpts.
// Tolerates both v0.3 (review_status/source_platform/score_band/...) and the old 28-col schema (status/platform/...).
function lStatus(l){return low(l.review_status||l.status);}
function lPlatform(l){return low(l.source_platform||l.platform)||'unknown';}
function lPriority(l){return low(l.review_priority);}
function lBand(l){return low(l.score_band);}
function lExcerpt(l){return cut(redact(str(l.evidence_excerpt||l.text_evidence||l.evidence_text)),140);}
function lHasContact(l){return !!(str(l.public_phone)||str(l.public_username)||str(l.public_profile_url)||str(l.contact_public));}
const activeLeads=leadSignals.filter(l=>['dismissed','rejected','duplicate','stale'].indexOf(lStatus(l))<0);
const newLeads=activeLeads.filter(l=>lStatus(l)==='new'||lStatus(l)==='needs_review').length;
// priority counts (fall back to band -> priority when review_priority absent)
function prio(l){const p=lPriority(l);if(p)return p;const b=lBand(l);return b==='high'?'high':(b==='medium'?'medium':'low');}
const hiLeads=activeLeads.filter(l=>prio(l)==='high').length;
const medLeads=activeLeads.filter(l=>prio(l)==='medium').length;
const loLeads=activeLeads.filter(l=>prio(l)==='low').length;
const contactsPresent=activeLeads.filter(l=>lHasContact(l)&&low(l.contact_use_policy)!=='do_not_use').length;
const contactsBlanked=activeLeads.filter(l=>low(l.contact_use_policy)==='do_not_use'||/contact_blanked/.test(low(l.privacy_flags))).length;
const intentCounts={};const painCounts={};
for(const l of activeLeads){const i=low(l.intent_type)||'unknown';intentCounts[i]=(intentCounts[i]||0)+1;
  str(l.pain_type).split(/\s*,\s*/).forEach(pn=>{if(pn&&pn!=='unknown')painCounts[pn]=(painCounts[pn]||0)+1;});}
const intentLine=Object.keys(intentCounts).map(k=>k+'='+intentCounts[k]).join(', ')||'(none)';
const topLeadPains=Object.keys(painCounts).sort((a,b)=>painCounts[b]-painCounts[a]).slice(0,4).map(k=>k+' ('+painCounts[k]+')').join(', ')||'(none)';
const leadLine=activeLeads.length?('public_lead_signals: '+activeLeads.length+' (new: '+newLeads+') · приоритет H/M/L: '+hiLeads+'/'+medLeads+'/'+loLeads+' · публичных контактов-свидетельств: '+contactsPresent+' (скрыто по политике: '+contactsBlanked+') · intents: '+intentLine+' · top pains: '+topLeadPains+' · политика: manual_review/aggregate_only, БЕЗ аутрича'):(leadSignals.length?('public_lead_signals: '+leadSignals.length+' строк, но активных нет — нечего выводить'):'(вкладка public_lead_signals пуста — запустить WF14 Lead Scout triage)');
// top 3-5 anonymized SAFE summaries (no contacts, no names, no profile URLs) — manager opens the row to verify.
const topLeads=activeLeads.slice().sort((a,b)=>(num(b.lead_score)-num(a.lead_score))).slice(0,5)
  .map((l,i)=>(i+1)+'. ['+(lBand(l)||'-')+' '+num(l.lead_score)+'] '+lPlatform(l)+' · '+(str(l.intent_type)||'-')+' · боль: '+(str(l.pain_type)||'-')+' · действие: '+(str(l.recommended_action)||'manual_review')+(lHasContact(l)?' · публичный контакт-свидетельство есть (см. строку, manual_review)':'')+'\n   «'+lExcerpt(l)+'»');
// --- v0.3 stakeholder executive digest: 5-7 clean bullets, no jargon, no raw ids.
const digest=[];
if(isNoData){digest.push('Данных за окно отчёта нет — нужно расширить фильтры или источники.');}
else{
  digest.push('Конкурентов в поле зрения: '+profNow.length+'; самый заметный — '+(topCompRows.length?cleanName(topCompRows[0]):'(нет)')+'.');
  if(topAng.length)digest.push('Главный рекламный угол рынка: '+topAng[0]+'.');
  const vk=sigNow.filter(s=>low(s.platform)==='vk')[0];
  const anySig=vk||sigNow[0];
  if(anySig)digest.push('Аудитория ('+str(anySig.platform)+'): вопросов '+num(anySig.question_count)+', возражений '+num(anySig.objection_count)+', покупательских сигналов '+num(anySig.buying_intent_count)+(str(anySig.top_pains)?('; боли: '+cut(anySig.top_pains,90)):'')+'.');
  if(activeLeads.length)digest.push('Публичных лид-сигналов: '+activeLeads.length+' ('+newLeads+' новых; приоритет H/M/L '+hiLeads+'/'+medLeads+'/'+loLeads+') — на ручную проверку менеджером, без какого-либо аутрича'+(contactsPresent?('; публичных контактов-свидетельств: '+contactsPresent):'')+'.');
  if(siteLines.length)digest.push('Сайты конкурентов: '+siteLines.length+' доменов в снапшоте'+(siteChanged?(', изменений: '+siteChanged):'')+'.');
  digest.push('Достоверность источников: '+(confScores.length?('в среднем '+confAvg+'/100'):'нет оценённых профилей')+'; источники смешанные (live + исторические + веб).');
  if(topAng.length)digest.push('Рекомендуемый фокус контента: '+cut(str((angNow.slice().sort((a,b)=>num(b.frequency)-num(a.frequency))[0]||{}).recommended_content_response),110)+'.');
}
const digestMd=digest.slice(0,7).map(b=>'- '+b).join('\n');
// --- v0.3 action blocks (deterministic, no outreach)
const mgrActions=isNoData?['Расширить фильтры/источники и перезапустить WF10 + WF12.']:[
  (activeLeads.length?('Просмотреть '+newLeads+' новых строк public_lead_signals (review_status=new, сначала приоритет=high): set accepted/rejected/duplicate/stale. Контакты — только manual_review, БЕЗ исходящих сообщений; outreach_allowed=false.'):'Запустить WF14 (Lead Scout triage), затем просмотреть public_lead_signals.'),
  'Проверить топ-конкурентов и углы (competitor_profiles / market_angles): отметить, кого мониторить дальше.',
  (siteLines.length?('Просмотреть изменения на сайтах конкурентов ('+siteChanged+' изменённых доменов).'):'Заполнить competitor_site_snapshots: прогнать WF04 по сайтам топ-конкурентов (по одобрению).')];
const contentActions=isNoData?[]:angNow.slice().sort((a,b)=>num(b.frequency)-num(a.frequency)).slice(0,3).map(a=>cut(str(a.recommended_content_response),130)).filter(Boolean);
const sourceActions=isNoData?['Запустить коннекторы (WF09/WF11/WF13) и WF08, затем WF10.']:[
  'Avito (WF09): live и история доступны — плановый прогон по лимитам стоимости (COSTS_AND_LIMITS).',
  'Telegram (WF11): публичный превью по отслеживаемым каналам протестирован — работает через approval gate, лимиты источника и фильтр релевантности. Следующее действие — добавить/отредактировать список отслеживаемых каналов и одобрить запуск (без аутрича).',
  'VK (WF13): будущее расширение источников — требует отдельного одобрения и VK-креденшла (техническая деталь: официальный API/HTTP-транспорт); не блокирует MVP-закрытие.',
  (siteLines.length?'Сайты: обновить снапшоты изменённых доменов контролируемым прогоном веб-снапшотов Stage 2 (WF04/WF06, по одобрению).':'Сайты: competitor_site_snapshots ещё не заполнен — после Stage 2 cleanup запустить контролируемый прогон веб-снапшотов по 3–5 топ-сайтам конкурентов (WF04/WF06, по одобрению).')];
function ol(arr){return arr.map((x,i)=>(i+1)+'. '+x).join('\n')||'(нет)';}
// --- mandatory source-mix label (DEC-108)
const SOURCE_MIX='mixed: live + historical/manual + web pipeline';
const reportType=isNoData?'no_data_notice':str(cfg.report_type);
// --- deterministic Markdown render (v0.3 stakeholder report)
const md=[
'# Market intelligence report '+str(cfg.report_id)+' (v0.3)',
'',
'- niche: '+str(cfg.niche_id)+' · region: '+str(cfg.region)+' · WF10 run: wf10_'+stamp+(prevStamp?(' · prev: wf10_'+prevStamp):' · prev: (none — first report, no trends)'),
'- **Источники: '+SOURCE_MIX+'** · rows_after_filters='+rowsAfter,
'',
'## Дайджест для руководителя (executive_digest)',digestMd,
'',
isNoData?('**NO DATA:** '+NO_DATA_TEXT):[
'## Снапшот конкурентов (competitor_snapshot)','профилей в снапшоте: '+profNow.length+' · площадки: '+platLine,
'','### Топ конкурентов',topComp.length?topComp.map((c,i)=>(i+1)+'. '+c).join('\n'):'(none in snapshot)',
'','## Топ офферов и цен (top_offers_and_prices)',offersPrices.length?offersPrices.map((o,i)=>(i+1)+'. '+o).join('\n'):'(офферы/цены не извлечены в этом снапшоте)',
'','## Сайты конкурентов (competitor_websites — Stage 2 reintegration)',siteLines.length?siteLines.map((s,i)=>(i+1)+'. '+s).join('\n'):'(competitor_site_snapshots пуст — это значит, что веб-снапшоты Stage 2 ещё не заполнены, а не сбой системы; после Stage 2 cleanup запустить контролируемый прогон WF04/WF06 — см. действия по источникам)',
webProfiles.length?('Профили WF10 с веб-источником: '+webProfiles.map(p=>cleanName(p)).join('; ')):'',
'','## Топ углов (market_angles_summary)',topAng.length?topAng.map((a,i)=>(i+1)+'. '+a).join('\n'):'(none in snapshot)',
'','## Аудитория и публичные лид-сигналы (aggregate-only)',(audSummary||'(no audience signals in snapshot)'),'',leadLine,
(topLeads.length?('\n### Топ публичных лид-сигналов (анонимно; контакты НЕ раскрываются — открыть строку для проверки)\n'+topLeads.join('\n')):''),
'_Лид-сигналы: только публичные свидетельства; контакты/телефоны/профили в отчёт не выводятся; outreach_allowed=false; решение и любой контакт — вручную менеджером._',
'','## План контента','plan: '+str(latest.plan_id)+' — '+str(latest.top_angles),
'','## Достоверность источников (source_confidence)',confLine
].join('\n'),
'',
'## Ограничения и source mix (limitations)',
'- '+SOURCE_MIX+' — агрегаты включают исторические/ручные записи, не только живой сбор последнего прогона.',
'- Тренды доступны только при >=2 прогонах WF10'+(prevStamp?'':' (этот отчёт — первый, трендов нет)')+'.',
'- Лид-сигналы — только публичные свидетельства; публичный профиль = evidence, НЕ разрешение на аутрич (CONTACT_AND_OUTREACH_POLICY).',
'- Контакты в отчёт не выводятся; рекомендации по аутричу не формируются.',
'',
'## Действия менеджера (manager_review_actions)',ol(mgrActions),
'',
'## Действия по контенту (content_actions)',ol(contentActions),
'',
'## Действия по источникам (source_collection_actions)',ol(sourceActions),
'',
'_Deterministic report v0.3 (DEC-112/122/128): факты только из вкладок; no LLM by default, no contacts, no outreach. $0._'
].join('\n');
// --- 25-column market_intelligence_reports row (MARKET_INTELLIGENCE_REPORT_SCHEMA.md v0.3)
return [{ json: {
  report_id:str(cfg.report_id),
  created_at:str(cfg.created_at),
  report_type:reportType,
  niche_id:str(cfg.niche_id),
  region:str(cfg.region),
  time_window_days:30,
  wf10_run_id:'wf10_'+stamp,
  prev_wf10_run_id:prevStamp?('wf10_'+prevStamp):'',
  source_mix:SOURCE_MIX,
  rows_after_filters:rowsAfter,
  top_competitors:isNoData?'':topComp.join(' | '),
  top_angles:isNoData?'':topAng.join(' | '),
  audience_summary:isNoData?'':redact(audSummary+(activeLeads.length?(' || '+leadLine):'')),
  content_plan_ref:str(latest.plan_id),
  report_markdown_path:'',
  llm_status:'disabled',
