// Build the evidence-bound Claude summary prompt v0.3 (DEC-122/128) + BUDGET GUARD (throws BEFORE the
// HTTP node). FACTS ONLY: deterministic report fields + aggregate audience/lead-signal summaries — never
// raw personal text dumps, never contact fields, never raw_market_records rows.
function str(v){return v==null?'':String(v).trim();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
const cfg=$('Set Report Config').first().json;
const rep=$('Build Deterministic Report').first().json;
const sys='Ты — аналитик рынка для руководителя кредитно-брокерской компании. Тебе дан ДЕТЕРМИНИРОВАННЫЙ отчёт (факты, собранные пайплайном). ЖЁСТКИЕ ПРАВИЛА: (1) НЕ выдумывай факты, конкурентов, цифры, цены, тренды; (2) НЕ упоминай и не выводи контакты; (3) НЕ рекомендуй аутрич/рассылки/обзвоны и не считай публичные профили разрешением на контакт; (4) если данных мало — прямо скажи об этом в source_limitations; (5) отвечай ТОЛЬКО валидным JSON-объектом без markdown и пояснений, ключи: executive_summary_ru (строка, до 120 слов), key_findings (массив строк, 3-6), market_risks (массив строк, 2-4), recommended_next_actions (массив строк, 3-5, только внутренние действия: контент, мониторинг, проверка данных), content_recommendations (массив строк, 2-4), source_limitations (массив строк, 1-3). Всё на русском.';
const facts={ report_id:str(rep.report_id), niche:str(rep.niche_id), region:str(rep.region), wf10_run_id:str(rep.wf10_run_id), prev_wf10_run_id:str(rep.prev_wf10_run_id), rows_after_filters:rep.rows_after_filters, source_mix:str(rep.source_mix), top_competitors:str(rep.top_competitors), top_angles:str(rep.top_angles), audience_and_public_lead_signal_aggregates:str(rep.audience_summary), content_plan_ref:str(rep.content_plan_ref) };
// --- budget guard (DEC-128): hard input cap + cost estimate BEFORE any HTTP call.
const maxInChars=Number(cfg.llm_max_input_chars)||8000;
const maxCost=Number(cfg.llm_max_estimated_cost_usd)||0.10;
const maxOut=Number(cfg.llm_max_tokens)||1200;
const userText='Детерминированный отчёт (JSON, единственный источник фактов):\n'+cut(JSON.stringify(facts),maxInChars);
const estInputTokens=Math.ceil((sys.length+userText.length)/4)+50;
const estCost=Math.round(((estInputTokens*(Number(cfg.llm_input_price_per_mtok)||3.0)+maxOut*(Number(cfg.llm_output_price_per_mtok)||15.0))/1000000)*10000)/10000;
if(estCost>maxCost){
  throw new Error('WF12 Claude budget guard (DEC-128): estimated cost $'+estCost+' exceeds llm_max_estimated_cost_usd=$'+maxCost+' (est input tokens='+estInputTokens+', max output tokens='+maxOut+'). Reduce llm_max_tokens / llm_max_input_chars or raise the budget consciously. No API call was made.');
}
const body={ model:str(cfg.llm_model)||'claude-sonnet-4-6', max_tokens:maxOut, system:sys, messages:[{ role:'user', content:userText }] };
return [{ json: Object.assign({}, rep, { llm_request_body: body, llm_facts_string: JSON.stringify(facts), llm_estimated_cost_usd: estCost, llm_estimated_input_tokens: estInputTokens }) }];

// Merge the Claude summary into the report row + track cost + quality flags (DEC-122/128). If the HTTP
// placeholder is still DISABLED, items pass through WITHOUT a Claude response body — this node then throws,
// so no fabricated summary can ever be written. With a real response: parse the JSON sections, compute cost
// (usage tokens x configured prices) and fill the llm_* columns of the 25-col report row.
function str(v){return v==null?'':String(v).trim();}
function arr(v){return Array.isArray(v)?v.map(x=>str(x)).filter(Boolean):[];}
const cfg=$('Set Report Config').first().json;
const prompt=$('Build Claude Summary Prompt').first().json;
const rep=$('Build Deterministic Report').first().json;
const resp=$input.first().json;
const content=resp&&Array.isArray(resp.content)?resp.content:null;
if(!content){
  throw new Error('WF12 Claude merge: no API response — the Claude HTTP placeholder node is DISABLED (inert by design, DEC-122). Enable it with a bound n8n credential only after operator approval; default runs write the deterministic report ($0).');
}
let text='';for(const b of content){ if(b&&b.type==='text'&&str(b.text))text+=b.text; }
if(resp.stop_reason==='refusal'||!str(text)){ throw new Error('WF12 Claude merge: empty or refused summary (stop_reason='+str(resp.stop_reason)+') — keep the deterministic report; investigate before retrying.'); }
const u=resp.usage||{};
const inTok=Number(u.input_tokens)||0, outTok=Number(u.output_tokens)||0;
const cost=Math.round(((inTok*(Number(cfg.llm_input_price_per_mtok)||3.0)+outTok*(Number(cfg.llm_output_price_per_mtok)||15.0))/1000000)*10000)/10000;
// --- parse the required JSON sections
const flags=[];
let parsed=null;
try{ parsed=JSON.parse(str(text).replace(/^```(json)?/,'').replace(/```$/,'').trim()); }catch(e){ parsed=null; }
if(resp.stop_reason==='max_tokens')flags.push('truncated_max_tokens');
let summaryRu='', recsRu='';
if(parsed&&typeof parsed==='object'){
  const kf=arr(parsed.key_findings), mr=arr(parsed.market_risks), na=arr(parsed.recommended_next_actions), cr=arr(parsed.content_recommendations), sl=arr(parsed.source_limitations);
  summaryRu=[str(parsed.executive_summary_ru), kf.length?('Ключевые выводы: '+kf.join(' · ')):'', mr.length?('Риски: '+mr.join(' · ')):'', sl.length?('Ограничения источников: '+sl.join(' · ')):''].filter(Boolean).join('\n');
  recsRu=[na.length?('Действия: '+na.join(' · ')):'', cr.length?('Контент: '+cr.join(' · ')):''].filter(Boolean).join('\n');
  if(!str(parsed.executive_summary_ru))flags.push('missing_executive_summary');
  if(!kf.length)flags.push('missing_key_findings');
}else{
  flags.push('non_json_output');
  summaryRu=str(text).slice(0,4000);
}
// --- anti-hallucination check: numbers in the output that are absent from the fact payload get flagged.
const factBlob=str(prompt.llm_facts_string);
const outNums=(summaryRu+' '+recsRu).match(/\d{2,}/g)||[];
if(outNums.some(n=>factBlob.indexOf(n)<0))flags.push('unverified_numbers_check_manually');
// --- outreach guard: flag if the model slipped into outreach language despite the system prompt.
if(/аутрич|рассылк|обзвон|написать ему|связаться с автором/i.test(summaryRu+' '+recsRu))flags.push('outreach_language_detected_review');
const llmStatus=flags.length?'ok_with_flags':'ok';
return [{ json: Object.assign({}, rep, {
  llm_status:llmStatus,
  llm_model:str(cfg.llm_model)||'claude-sonnet-4-6',
  llm_input_tokens:inTok,
  llm_output_tokens:outTok,
  llm_cost_usd:cost,
  llm_summary_ru:summaryRu.slice(0,4000),
  llm_recommendations_ru:recsRu.slice(0,2000),
  llm_quality_flags:flags.join(', '),
  notes:str(rep.notes)+' || llm_summary added (model='+(str(cfg.llm_model)||'claude-sonnet-4-6')+', input_tokens='+inTok+', output_tokens='+outTok+', cost_usd='+cost+', flags='+(flags.join('/')||'none')+'); evidence-bound prompt + budget guard (DEC-128), no invented facts/contacts/outreach.'
}) }];

// Build ONE live_source_runs row for the report layer (23 columns, DEC-126/128): logs whether the run
